class Kpi(BaseModel):
    """
    One KPI, as the registry holds it (K11) and the discovery screen renders it. The formula
    fields are the contract shape; the presentation fields are what the registry screen shows.
    `feasibility` is embedded so the list renders its ready/partial/blocked badges without a
    call per row -- it is still a set difference, computed on read, never stored.

    """

    id: str
    identifier: str = Field(
        ...,
        description="`<concept>__<name>`, stable across edits. What provenance and gold rows reference.",
    )
    name: str
    description: str
    business_area: str = Field(
        ...,
        description="A business area identifier. In 1.0.0 this is the shipped `business_area` vocabulary\n(`egpt_retail/ontology/vocabularies.json`) plus whatever a customer overlay adds, so it is\na string validated at runtime against the deployment's vocabulary, not an enum.\n",
        examples=["inventory", "sales", "supply_chain"],
    )
    subject_area: str | None = ""
    concept: str | None = None
    grain: str = Field(
        ...,
        description="A term from the deployment's `grain` vocabulary (shipped ontology plus overlay). A string validated at runtime, not an enum -- see CHANGELOG 2.0.0 of the KPI formula shape.",
        examples=["overall", "product", "supplier", "location", "time_period"],
    )
    result_shape: ResultShape
    dialect: Dialect | None = None
    sql: str | None = Field(
        None,
        description="The formula with `{named}` placeholders. Returned only to callers holding `kpis:write`; a viewer sees the field absent.",
    )
    formula_explanation: FormulaExplanation | None = Field(
        None,
        description="A human-readable rendering of `sql`, for the FORMULA card. Gated behind `kpis:write` the same way `sql` is (`_may_read_sql`) -- its labels can name the same columns/tables the formula reads, so it is exactly the schema detail that gate exists to withhold from a `kpis:read`-only caller. Null for a hand-authored KPI, one adopted before this field existed, or a viewer without the scope.",
    )
    column_usage: list[ColumnUsage] | None = Field(
        [],
        description="The formula's own account of which columns it reads and why -- \"the columns it uses\". Gated behind `kpis:write` the same way `sql` is; always `[]` for a `kpis:read`-only caller, a hand-authored KPI, or one adopted before this field existed. This KPI's own `table_usage` (fact/lookup role, join notes) is not a separate list here -- it rides along on each of `source_table_status`'s entries instead, since both describe the same tables.",
        validate_default=True,
    )
    source_tables: list[str]
    parameters: list[KpiParameter] | None = None
    time_window: TimeWindow | None = None
    validated_against_snapshot: str | None = None
    level: KpiLevel | None = None
    unit: str | None = ""
    industry_benchmark: str | None = ""
    rationale: str | None = Field(
        None,
        description="Why the model proposed this KPI -- the sentence naming the tables or concepts it derives from, carried over from `KpiSuggestion.rationale` when the KPI was adopted. Null on a KPI authored by hand or adopted before this field existed.",
    )
    business_value: str | None = Field(
        None,
        description="What tracking this KPI lets someone decide or catch, carried over from `KpiSuggestion.business_value` on adopt. Null on a KPI authored by hand or adopted before this field existed.",
    )
    active: bool
    source: KpiOrigin
    dataset_ids: list[str] | None = None
    process_ids: list[str] | None = None
    dashboard_names: list[str] | None = Field(
        [],
        description="Names of the dashboards with a tile naming this KPI, sorted. Computed on read from the dashboard table, never stored on the KPI itself -- the same reference check `DELETE /kpis/{kpi_id}` already runs to refuse deleting a KPI still in use, generalized into a read path. Empty when nothing references it yet.",
    )
    source_table_status: list[SourceTableStatus] | None = Field(
        [],
        description="Each of `source_tables`' most recent load, from the warehouse's own load history -- only populated by `GET /kpis/{kpi_id}` (a list read never pays for N per-row warehouse queries), and only for a table that resolves to a known landed stream and has actually loaded at least once. Always `[]`, never a partial failure, when the warehouse is unreachable -- this is enrichment for the detail panel, not core KPI data.",
        validate_default=True,
    )
    feasibility: Feasibility
    updated_at: AwareDatetime | None = Field(None, description="RFC 3339, always UTC.")


class KpiSeries(BaseModel):
    """
    One KPI's value over its last business dates, read from `gold.kpi_value` -- the same rows
    a dashboard's `line`/`bar` tile plots, addressed by KPI rather than by tile. One point per
    business date the KPI materialised for; a night with no row is absent, not `null` (`null`
    means the formula returned NULL that night). Nothing is recomputed on read.

    A KPI whose grain is not `overall` has one row per dimension value each night; `dimension`
    names the one the points follow (the caller's choice, else the first seen) and
    `dimensions` lists every value the latest night carried, so a screen can offer the others.

    """

    kpi_identifier: str
    grain: str = Field(
        ...,
        description="A term from the deployment's `grain` vocabulary (shipped ontology plus overlay). A string validated at runtime, not an enum -- see CHANGELOG 2.0.0 of the KPI formula shape.",
        examples=["overall", "product", "supplier", "location", "time_period"],
    )
    interval: KpiSeriesInterval
    days: int = Field(
        ...,
        description="The window the points were read over, ending at `as_of`.",
        ge=1,
    )
    unit: str | None = ""
    dimension: dict[str, Any] | None = Field(
        ...,
        description="The grain-key values the points follow; `null` for an `overall` KPI.",
    )
    dimensions: list[dict[str, Any]] = Field(
        ...,
        description="Every dimension the latest business date carried, in gold's row order, capped at 25.",
    )
    points: list[SeriesPoint] = Field(..., description="Oldest first.")
    value: float | None = Field(
        ...,
        description="The latest point's value; what a `number` tile of this KPI shows.",
    )
    delta: float | None = Field(
        ...,
        description="`value` minus the previous point's value; `null` with fewer than two points.",
    )
    as_of: AwareDatetime | None = None
    computed_at: AwareDatetime | None = None
    status: KpiHealthStatus
    provenance_ref: str | None = None


class KpiSuggestionCurrent(BaseModel):
    """
    The suggestions a person should see now, kept between visits. Unlike a run (which is one
    pass of the agent and is read by id), this is the standing answer to "what has the platform
    proposed that I have not yet adopted or dismissed": the newest successful run of each
    source (and of the deployment's own warehouse), merged, less every suggestion already in
    the registry and every one a person dismissed (`POST /kpis/suggestions/dismissals`). A
    suggestion appears once even if more than one source proposed it.

    `generating` and `failed` are for the screen to say what is happening behind the list: a
    run still working (a source was just connected, and its suggestions are on the way) and
    the most recent run that failed with no later success to replace it (so a missing list is
    explained rather than silent). Both are runs with `result` omitted -- the list is
    `suggestions`.

    """

    suggestions: list[KpiSuggestion]
    notes: str = Field(
        ...,
        description="What the runs that produced `suggestions` said was missing (the skill template's refusal shape). Empty when nothing was.",
    )
    generating: KpiSuggestionRun | None = Field(
        None,
        description="A run that is `queued` or `running` now, newest first if several are; poll it with `GET /kpis/suggestions/{run_id}` and read this again when it finishes. Null when nothing is running.",
    )
    failed: KpiSuggestionRun | None = Field(
        None,
        description="The newest run that ended `failed` and has not been superseded by a later success for the same source. Null when there is none.",
    )


class KpiWrite(BaseModel):
    """
    Authoring a KPI. The formula is validated at construction (declared parameters match placeholders, source tables cover the formula) and refused with 422 naming the defect.
    """

    identifier: str | None = None
    name: str
    description: str
    business_area: str = Field(
        ...,
        description="A business area identifier. In 1.0.0 this is the shipped `business_area` vocabulary\n(`egpt_retail/ontology/vocabularies.json`) plus whatever a customer overlay adds, so it is\na string validated at runtime against the deployment's vocabulary, not an enum.\n",
        examples=["inventory", "sales", "supply_chain"],
    )
    subject_area: str | None = None
    concept: str | None = None
    grain: str = Field(
        ...,
        description="A term from the deployment's `grain` vocabulary (shipped ontology plus overlay). A string validated at runtime, not an enum -- see CHANGELOG 2.0.0 of the KPI formula shape.",
        examples=["overall", "product", "supplier", "location", "time_period"],
    )
    result_shape: ResultShape | None = None
    dialect: Dialect | None = None
    sql: str
    formula_explanation: FormulaExplanation | None = Field(
        None,
        description="The suggestion's `formula_explanation`, resent verbatim when adopting a proposal so the registry keeps it. Optional; an update that omits it carries the stored value forward like every other optional field here.",
    )
    column_usage: list[ColumnUsage] | None = Field(
        None,
        description="The suggestion's `column_usage`, resent verbatim when adopting a proposal. Optional; an update that omits it carries the stored value forward like every other optional field here.",
    )
    table_usage: list[TableUsage] | None = Field(
        None,
        description="The suggestion's `table_usage`, resent verbatim when adopting a proposal. Optional; an update that omits it carries the stored value forward like every other optional field here.",
    )
    source_tables: list[str]
    parameters: list[KpiParameter] | None = None
    time_window: TimeWindow | None = None
    level: KpiLevel | None = None
    unit: str | None = None
    industry_benchmark: str | None = None
    rationale: str | None = Field(
        None,
        description="The suggestion's `rationale`, resent verbatim when adopting a proposal so the registry keeps it. Optional; an update that omits it carries the stored value forward like every other optional field here.",
    )
    business_value: str | None = Field(
        None,
        description="The suggestion's `business_value`, resent verbatim on adopt. Optional, carried forward on update when omitted.",
    )
    active: bool | None = None
    dataset_ids: list[str] | None = None
    process_ids: list[str] | None = None


class Plan(BaseModel):
    """
    A view over the compiled workflow, never authored separately. Steps four and five of the prototype's wizard render this.
    """

    use_case_id: str
    version: int
    workflow_component_id: str | None = None
    steps: list[PlanStep]
    compiled_at: AwareDatetime = Field(..., description="RFC 3339, always UTC.")


class Provenance(BaseModel):
    """
    The record every answer writes (alignment rule: "every answer writes a provenance
    record"). Its shape is fixed here in phase zero so that R7 implements it rather than
    designs it, and so the citation panel in the playground renders one thing. Holds what was
    read, what was executed, what was sampled, how fresh each input was, what retrieval
    returned, and which model tier answered.

    """

    run_id: str
    use_case_id: str | None = None
    produced_at: AwareDatetime = Field(..., description="RFC 3339, always UTC.")
    semantic_snapshot: str = Field(
        ...,
        description="The semantic snapshot version every read in this run was answered from.",
    )
    vocabulary_version: str | None = Field(
        None,
        description="The shipped vocabulary version closed-set values were validated against.",
    )
    skill: SkillRef | None = None
    model_tier: ProvenanceModelTier
    datasets_read: list[DatasetRead]
    sql_executed: list[SqlExecution]
    rows_sampled: list[RowSample] | None = None
    freshness: list[FreshnessStamp] | None = None
    retrieval_hits: list[RetrievalHit] | None = None


class Report(BaseModel):
    id: str
    title: str
    items: list[ReportItem]
    created_at: AwareDatetime = Field(..., description="RFC 3339, always UTC.")
    updated_at: AwareDatetime = Field(..., description="RFC 3339, always UTC.")


class ReportList(BaseModel):
    active_report_id: str | None
    reports: list[Report]


class Spec(BaseModel):
    """
    What the author asked for, extracted by the spec-extraction agent (R9, Lane R's first
    skill). Every closed-set value comes from the semantic layer and the vocabulary; an entity
    the deployment does not have cannot appear here, it appears in `notes` instead.

    """

    use_case_id: str
    question: str
    business_area: str = Field(
        ...,
        description="A business area identifier. In 1.0.0 this is the shipped `business_area` vocabulary\n(`egpt_retail/ontology/vocabularies.json`) plus whatever a customer overlay adds, so it is\na string validated at runtime against the deployment's vocabulary, not an enum.\n",
        examples=["inventory", "sales", "supply_chain"],
    )
    entities: list[SpecEntity]
    kpi_identifiers: list[str]
    grain: str = Field(
        ...,
        description="A term from the deployment's `grain` vocabulary (shipped ontology plus overlay). A string validated at runtime, not an enum -- see CHANGELOG 2.0.0 of the KPI formula shape.",
        examples=["overall", "product", "supplier", "location", "time_period"],
    )
    time_window: TimeWindow | None = None
    delivery: DeliveryChannel | None = None
    notes: str = Field(
        ...,
        description="Empty on a clean extraction; otherwise what the question asked for that the deployment cannot express.",
    )
    questions: list[str] | None = Field(
        None,
        description="Clarifying questions for the author (1.1.0, R9). Where `notes` records what could not be\nexpressed, this records what the agent needs answered before the spec is complete -- a\nmetric it could not match to the registry, or a sentence ambiguous about whether the use\ncase should act. Empty on a clean extraction. A question is the refusal shape for an\nunknown; the agent never coins a value to avoid asking one.\n",
    )
    extracted_by: SkillRef
    semantic_snapshot: str | None = None
